    owner, acc = lines[0].split(',')
    account = BankAccount(acc.strip(), owner.strip())
    for tx in lines[1:]:
        action, amt = tx.split(':')
        amt = float(amt.strip())
        if action.strip() == 'DEP':
            account.deposit(amt)
        elif action.strip() == 'WIT':
            account.withdraw(amt)
    print(account.get_summary())

