class CircularQueue:
    def __init__(self, k: int):
        self.cap = k
        self.q = [None] * k
        self.head = 0
        self.tail = 0
        self.size = 0

    def enqueue(self, val) -> bool:
        if self.size == self.cap:
            return False
        self.q[self.tail] = val
        self.tail = (self.tail + 1) % self.cap
        self.size += 1
        return True

