class BSTNode:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, val):
        if not self.root:
            self.root = BSTNode(val)
        else:
            self._insert_recursive(self.root, val)

    def _insert_recursive(self, curr, val):
        if val < curr.val:
            if curr.left is None:
                curr.left = BSTNode(val)
            else:
                self._insert_recursive(curr.left, val)
        elif val > curr.val:
            if curr.right is None:
                curr.right = BSTNode(val)
            else:
                self._insert_recursive(curr.right, val)

    def search(self, target) -> bool:
        return self._search_recursive(self.root, target)

    def _search_recursive(self, curr, target) -> bool:
        if curr is None:
            return False
        if curr.val == target:
            return True
        if target < curr.val:
            return self._search_recursive(curr.left, target)
        return self._search_recursive(curr.right, target)

    def inorder(self):
        result = []
        def traverse(node):
            if node:
                traverse(node.left)
                result.append(node.val)
                traverse(node.right)
        traverse(self.root)
        return result

