import sys

class Node:
    def __init__(self, key=0, val=0):
        self.key = key
        self.val = val
        self.prev = None
        self.next = None

class LRUCache:
    def __init__(self, capacity: int):
        self.cap = capacity
        self.map = {}
        self.head = Node()
        self.tail = Node()
        self.head.next = self.tail
        self.tail.prev = self.head

    def _remove(self, node):
        node.prev.next = node.next
        node.next.prev = node.prev

    def _add(self, node):
        node.prev = self.tail.prev
        node.next = self.tail
        self.tail.prev.next = node
        self.tail.prev = node

    def get(self, key: int) -> int:
        if key not in self.map:
            return -1
        node = self.map[key]
        self._remove(node)
        self._add(node)
        return node.val

    def put(self, key: int, value: int) -> None:
        if key in self.map:
            self._remove(self.map[key])
        elif len(self.map) >= self.cap:
            lru = self.head.next
            self._remove(lru)
            del self.map[lru.key]
        node = Node(key, value)
        self.map[key] = node
        self._add(node)

    def get_order(self):
        res = []
        curr = self.head.next
        while curr != self.tail:
            res.append((curr.key, curr.val))
            curr = curr.next
        return res

def solve():
    lines = [l.strip() for l in sys.stdin.read().strip().split('
') if l.strip()]
    if not lines:
        return
    cap = int(lines[0])
    cache = LRUCache(cap)
    for line in lines[1:]:
        parts = line.split()
        cmd = parts[0]
        if cmd == 'PUT':
            cache.put(int(parts[1]), int(parts[2]))
        elif cmd == 'GET':
            print(cache.get(int(parts[1])))
    print(f"LRU -> {cache.get_order()}")

if __name__ == '__main__':
    solve()

